const fs = require('fs');
const http = require('http');

const options = {
  hostname: 'localhost',
  port: 20128,
  path: '/v1/models',
  method: 'GET',
  headers: {
    'Authorization': 'Bearer sk-3f82ee8c02edcb90-f93add-f946493a'
  }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => { data += chunk; });
  res.on('end', () => {
    try {
      const json = JSON.parse(data);
      const models = json.data || json;
      const freeModels = models.filter(m => 
        (m.name && m.name.includes('🆓')) || 
        (m.pricing && m.pricing.input === 0 && m.pricing.output === 0)
      );
      console.log('Total Models:', models.length);
      console.log('Free Models Found:', freeModels.length);
      console.log('Sample Free Models:');
      freeModels.slice(0, 15).forEach(m => console.log('-', m.id, '(', m.name, ')'));
    } catch (e) {
      console.error('Error parsing response:', e);
    }
  });
});
req.on('error', (e) => console.error(e));
req.end();
""}

